#pragma once
#include <cstdint>
namespace ks{class SerialTransmitTask final{public:enum class Stage{RetainFirst,RetainSecond,ReadProducer,Normalize,LocateData,ResolveData,WriteData,NextProducer,MaskProducer,ReadConsumer,CompareQueue,AdmitSpace,WriteProducer,RetainCritical,MaskCritical,Enable,WriteEnable,RestoreCritical,RestoreSecond,RestoreFirst,Finish,Complete};enum class Read{Producer,Consumer,Input};enum class Write{Data,Producer,Enable};Stage stage()const{return stage_;}uint16_t producer()const{return producer_;}uint16_t consumer()const{return consumer_;}uint16_t nextProducer()const{return next_;}uint8_t data()const{return data_;}uint32_t dataAddress()const{return (0xffed70u+producer_)&0xffffffu;}
template<class Clock>unsigned nextClocks(Clock&&clock)const{switch(stage_){case Stage::RetainFirst:return 20;case Stage::RetainSecond:return 20;case Stage::ReadProducer:return 15;case Stage::Normalize:return 3;case Stage::LocateData:return 9;case Stage::ResolveData:return 3;case Stage::WriteData:return 3+clock(Write::Data);case Stage::NextProducer:return 3;case Stage::MaskProducer:return 6;case Stage::ReadConsumer:return 15;case Stage::CompareQueue:return 3;case Stage::AdmitSpace:return 3;case Stage::WriteProducer:return 15;case Stage::RetainCritical:return 14;case Stage::MaskCritical:return 6;case Stage::Enable:return 3;case Stage::WriteEnable:return 3+clock(Write::Enable);case Stage::RestoreCritical:return 14;case Stage::RestoreSecond:return 20;case Stage::RestoreFirst:return 20;case Stage::Finish:return 17; default:return 0;}}
template<class Reader,class Writer,class Clock>unsigned advanceBefore(unsigned available,Reader&&read,Writer&&write,Clock&&clock){unsigned used=0;while(auto cost=nextClocks(clock)){if(cost>available-used)break;switch(stage_){case Stage::RetainFirst:stage_=Stage::RetainSecond;break;case Stage::RetainSecond:stage_=Stage::ReadProducer;break;case Stage::ReadProducer:producer_=uint16_t(read(Read::Producer));stage_=Stage::Normalize;break;case Stage::Normalize:stage_=Stage::LocateData;break;case Stage::LocateData:stage_=Stage::ResolveData;break;case Stage::ResolveData:stage_=Stage::WriteData;break;case Stage::WriteData:data_=uint8_t(read(Read::Input));write(Write::Data,data_);stage_=Stage::NextProducer;break;case Stage::NextProducer:next_=uint16_t(producer_+1);stage_=Stage::MaskProducer;break;case Stage::MaskProducer:next_&=255;stage_=Stage::ReadConsumer;break;case Stage::ReadConsumer:consumer_=uint16_t(read(Read::Consumer));stage_=Stage::CompareQueue;break;case Stage::CompareQueue:stage_=Stage::AdmitSpace;break;case Stage::AdmitSpace:stage_=consumer_==next_?Stage::ReadConsumer:Stage::WriteProducer;break;case Stage::WriteProducer:write(Write::Producer,next_);stage_=Stage::RetainCritical;break;case Stage::RetainCritical:stage_=Stage::MaskCritical;break;case Stage::MaskCritical:stage_=Stage::Enable;break;case Stage::Enable:stage_=Stage::WriteEnable;break;case Stage::WriteEnable:write(Write::Enable,0xf0);stage_=Stage::RestoreCritical;break;case Stage::RestoreCritical:stage_=Stage::RestoreSecond;break;case Stage::RestoreSecond:stage_=Stage::RestoreFirst;break;case Stage::RestoreFirst:stage_=Stage::Finish;break;case Stage::Finish:stage_=Stage::Complete;break; default:break;}used+=cost;}return used;}private:Stage stage_=Stage::RetainFirst;uint16_t producer_=0,consumer_=0,next_=0;uint8_t data_=0;};}
